def cargar(apps, editor):
    """Tipos para afinar el mapa de riesgo con lo que la gente vio, y la pregunta de duración en los daños."""
    TipoRiesgo = apps.get_model("reportes", "TipoRiesgo")
    TipoRiesgo.objects.filter(codigo="dano_infraestructura").update(pide_duracion=True)
    nuevos = [
        ("aqui_se_inundo", "Aquí se inundó", "marca", 7 * 24, 30),           # ya pasó; queda una semana a la vista
        ("aqui_no_paso", "Aquí no se inundó", "seco", 3 * 24, 31),           # todo bien en este punto
        ("zona_de_riesgo", "Aquí siempre se inunda", "alerta", 30 * 24, 32),  # lo que sabe el barrio
    ]
    for codigo, nombre, icono, plazo, orden in nuevos:
        TipoRiesgo.objects.get_or_create(codigo=codigo, defaults={"nombre": nombre, "icono": icono, "plazo_horas": plazo, "orden": orden, "clase": "observa"})


